{
  "items": [
    {
      "name": "Nat.pow_log_le_add_one",
      "module_name": "Mathlib.Data.Nat.Log",
      "kind": "theorem",
      "type": "∀ (b x : ℕ), b ^ Nat.log b x ≤ x + 1"
    },
    {
      "name": "Nat.le_log_of_pow_le",
      "module_name": "Mathlib.Data.Nat.Log",
      "kind": "theorem",
      "type": "∀ {b x y : ℕ}, 1 < b → b ^ x ≤ y → x ≤ Nat.log b y"
    },
    {
      "name": "Nat.lt_pow_of_log_lt",
      "module_name": "Mathlib.Data.Nat.Log",
      "kind": "theorem",
      "type": "∀ {b x y : ℕ}, 1 < b → Nat.log b y < x → y < b ^ x"
    },
    {
      "name": "Nat.pow_le_of_le_log",
      "module_name": "Mathlib.Data.Nat.Log",
      "kind": "theorem",
      "type": "∀ {b x y : ℕ}, y ≠ 0 → x ≤ Nat.log b y → b ^ x ≤ y"
    },
    {
      "name": "Nat.le_pow_clog",
      "module_name": "Mathlib.Data.Nat.Log",
      "kind": "theorem",
      "type": "∀ {b : ℕ}, 1 < b → ∀ (x : ℕ), x ≤ b ^ Nat.clog b x"
    }
  ]
}
